fields.InputDefinition:
{
  "goal": "IMPORTANT: To open the 'Members' entity, use the LEFT sidebar 'Search entities...' box — type 'Members' and click the node named EXACTLY 'Members' (individual member people, ~2000 records; NOT 'Board Members', 'Campaign Members', 'Member Follows', 'Memberships', 'Membership Types', 'Chapter Memberships', or 'Committee Memberships'). Do NOT fight a group expand-chevron. Open the 'Members' entity grid (~2000 records across many pages). Use the grid's pagination control at the bottom to advance to the next page (page 2); verify a different page of member rows is shown. Do not repeatedly toggle the same control. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
